<script setup>import { stores } from '../../api/mock'; import AppIcon from '../../components/AppIcon.vue'</script>
<template><div class="resource-page"><div class="store-overview"><div><span>门店总数</span><strong>5</strong><small>4 营业 · 1 筹备</small></div><div><span>在线收银机</span><strong>11 / 15</strong><small>在线率 73.3%</small></div><div><span>今日营业额</span><strong>¥85,583</strong><small>目标完成 86.3%</small></div></div><section class="resource-card"><header class="resource-tools"><div><h2>门店与设备</h2><p>查看营业状态、收银设备、经营进度与基础资料</p></div><button class="primary"><AppIcon name="plus"/>新增门店</button></header><div class="store-grid"><article v-for="store in stores" :key="store.storeCode"><header><span class="store-symbol"><AppIcon name="store" :size="22"/></span><div><h3>{{store.name}}</h3><p>{{store.storeCode}} · {{store.city}}</p></div><em :class="store.status.toLowerCase()">{{store.status==='OPEN'?'营业中':'筹备中'}}</em></header><p class="address">{{store.address}}</p><dl><div><dt>今日营业额</dt><dd>¥{{store.todaySales.toLocaleString()}}</dd></div><div><dt>订单</dt><dd>{{store.todayOrders}} 笔</dd></div><div><dt>收银设备</dt><dd>{{store.onlineRegisters}} / {{store.registerCount}} 在线</dd></div></dl><div class="goal"><span>今日目标</span><b>{{store.targetRate}}%</b><i><em :style="{width:store.targetRate+'%'}"></em></i></div><footer><button>查看经营</button><button>设备管理</button><button>门店设置</button></footer></article></div></section></div></template>
